public class InnerRouterOutputRouterOutputProtocolConfigurationFactory(Action<Humidifier.MediaConnect.RouterOutputTypes.RouterOutputProtocolConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.RouterOutputTypes.RouterOutputProtocolConfiguration>
{

    internal InnerRouterOutputSrtCallerRouterOutputConfigurationFactory SrtCallerFactory { get; set; }

    internal InnerRouterOutputSrtListenerRouterOutputConfigurationFactory SrtListenerFactory { get; set; }

    internal InnerRouterOutputRtmpPushRouterOutputConfigurationFactory RtmpPushFactory { get; set; }

    internal InnerRouterOutputRistRouterOutputConfigurationFactory RistFactory { get; set; }

    internal InnerRouterOutputRtpRouterOutputConfigurationFactory RtpFactory { get; set; }

    protected override Humidifier.MediaConnect.RouterOutputTypes.RouterOutputProtocolConfiguration Create()
    {
        var routerOutputProtocolConfigurationResult = CreateRouterOutputProtocolConfiguration();
        factoryAction?.Invoke(routerOutputProtocolConfigurationResult);

        return routerOutputProtocolConfigurationResult;
    }

    private Humidifier.MediaConnect.RouterOutputTypes.RouterOutputProtocolConfiguration CreateRouterOutputProtocolConfiguration()
    {
        var routerOutputProtocolConfigurationResult = new Humidifier.MediaConnect.RouterOutputTypes.RouterOutputProtocolConfiguration();

        return routerOutputProtocolConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.RouterOutputTypes.RouterOutputProtocolConfiguration result)
    {
        base.CreateChildren(result);

        result.SrtCaller ??= SrtCallerFactory?.Build();
        result.SrtListener ??= SrtListenerFactory?.Build();
        result.RtmpPush ??= RtmpPushFactory?.Build();
        result.Rist ??= RistFactory?.Build();
        result.Rtp ??= RtpFactory?.Build();
    }

} // End Of Class

